"""Parser for CSV files that partner stations drop via SFTP."""
import csv
import datetime as dt
import functools

from tidewater.models import Reading
from tidewater.transform import units

_UTC = dt.timezone.utc


@functools.lru_cache(maxsize=4096)
def _day_epoch(day: str) -> int:
    return int(dt.datetime.fromisoformat(day).replace(tzinfo=_UTC).timestamp())


def _epoch(ts: str) -> int:
    # "2026-10-01T12:34:56" -> epoch seconds, UTC
    if len(ts) != 19 or ts[10] != "T":
        return int(dt.datetime.fromisoformat(ts).replace(tzinfo=_UTC).timestamp())
    return _day_epoch(ts[:10]) + int(ts[11:13]) * 3600 + int(ts[14:16]) * 60 + int(ts[17:19])


def parse_file(path, station_id):
    out = []
    with open(path, newline="") as fh:
        for row in csv.DictReader(fh):
            ts = dt.datetime.fromisoformat(row["timestamp"]).replace(tzinfo=dt.timezone.utc)
            if "level_mm" in row:
                level_mm = int(row["level_mm"])
            else:
                level_mm = units.mm_from_m(float(row["level_m"]))
            out.append(
                Reading(
                    station_id=station_id,
                    observed_at=int(ts.timestamp()),
                    level_mm=level_mm,
                    source="csv_drop",
                    battery_mv=int(row["batt_mv"]) if row.get("batt_mv") else None,
                )
            )
    return out

